<div x-data=\"hero()\" class=\"relative min-h-screen flex items-center justify-center px-4\">\n    <div class=\"container mx-auto grid md:grid-cols-2 gap-12 items-center\">\n        <!-- Left Column: Headline & CTAs -->\n        <div class=\"text-left\">\n            <h1 class=\"font-serif text-5xl md:text-7xl text-[#111111] leading-tight drop-shadow-sm\">\n                <span x-text=\"typedText\"></span><span class=\"blinking-cursor\">█</span>\n            </h1>\n            <p class=\"mt-6 font-sans text-lg text-gray-700 max-w-lg\">AISOFT is a research and development lab building the foundational layer for the next generation of intelligent systems.</p>\n            <div class=\"mt-8 flex space-x-4\">\n                <button class=\"px-6 py-3 bg-[#111111] text-white font-sans rounded-md hover:bg-black transition-colors\">Request Access</button>\n                <button class=\"px-6 py-3 border border-black/20 text-[#111111] font-sans rounded-md hover:bg-orange-100/50 hover:border-orange-300 transition-colors\">Read Docs</button>\n            </div>\n        </div>\n\n        <!-- Right Column: Code Visualizer -->\n        <div class=\"bg-white p-4 sm:p-6 rounded-lg shadow-2xl border border-black/5 font-mono text-sm leading-relaxed\">\n            <div class=\"flex items-center pb-3 border-b border-black/10\">\n                <div class=\"flex space-x-1.5\">\n                    <div class=\"w-3 h-3 rounded-full bg-red-400\"></div>\n                    <div class=\"w-3 h-3 rounded-full bg-yellow-400\"></div>\n                    <div class=\"w-3 h-3 rounded-full bg-green-400\"></div>\n                </div>\n                <span class=\"ml-4 text-xs text-gray-500\">/system/status.json</span>\n            </div>\n            <div class=\"pt-4 overflow-x-auto\">\n                <pre class=\"whitespace-pre-wrap\"><code class=\"language-json\" x-html=\"highlightedCode\"></code></pre>\n            </div>\n        </div>\n    </div>\n</div>\n\n<script>\nfunction hero() {\n    return {\n        fullText: 'AISOFT INTELLIGENCE',\n        typedText: '',\n        codeIndex: 0,\n        highlightedCode: '',\n        codeSnippets: [\n            {\n                status: 'OPTIMIZING',\n                sector: 'vizag_tech_corridor',\n                load: 0.78,\n                nodes: 4096\n            },\n            {\n                status: 'COMPILING_KERNEL',\n                sector: 'coimbatore_agri_grid',\n                load: 0.62,\n                nodes: 3128\n            },\n            {\n                status: 'ROUTING_DATA',\n                sector: 'bangalore_bio_cluster',\n                load: 0.89,\n                nodes: 5012\n            },\n            {\n                status: 'IDLE',\n                sector: 'mumbai_logistics_net',\n                load: 0.21,\n                nodes: 1845\n            }\n        ],\n\n        init() {\n            // Typewriter effect\n            let i = 0;\n            const typing = setInterval(() => {\n                if (i < this.fullText.length) {\n                    this.typedText += this.fullText.charAt(i);\n                    i++;\n                } else {\n                    clearInterval(typing);\n                }\n            }, 100);\n\n            // Code streaming effect\n            this.updateCode();\n            setInterval(() => {\n                this.codeIndex = (this.codeIndex + 1) % this.codeSnippets.length;\n                this.updateCode();\n            }, 2500);\n        },\n\n        updateCode() {\n            const data = this.codeSnippets[this.codeIndex];\n            const jsonString = JSON.stringify(data, null, 2);\n            this.highlightedCode = this.applySyntaxHighlighting(jsonString);\n        },\n\n        applySyntaxHighlighting(jsonString) {\n            return jsonString\n                .replace(/(\"|\\w+)\s*:/g, '<span class=\"text-indigo-600\">$&</span>')\n                .replace(/:\\s*(\".*\")/g, (match, p1) => `: <span class=\"text-orange-600\">${p1}</span>`)\n                .replace(/:\\s*([0-9\\.]+)/g, (match, p1) => `: <span class=\"text-teal-600\">${p1}</span>`);\n        }\n    }\n}\n</script>\n\n<style>\n.blinking-cursor {\n    color: #FF6B00;\n    animation: blink 1s step-end infinite;\n}\n\n@keyframes blink {\n    from, to { color: transparent }\n    50% { color: #FF6B00; }\n}\n</style>